p: oScan.ebelp,\n                werks: oScan.werks,\n                lgort: oScan.lgort,\n                matnr: oScan.matnr,\n                quantity: Number(oScan.quantity),\n                meins: oScan.meins,\n                bwart: oScan.bwart\n  +
          }\n        ];\n\n        this.updateQueue(aItems);\n        this.getScanModel().setData(this.createEmptyScanData());\n\n        MessageToast.show(\"입고 대기열에 추가했습니다.\");\n    }\n\n    public onDeleteQueue(oEvent: Event): void {\n        const sPa+
th = (oEvent.getSource() as Control)\n            .getBindingContext(\"queue\")\n            ?.getPath();\n\n        const iIndex = Number(sPath?.split(\"/\").pop());\n\n        if (Number.isNaN(iIndex)) {\n            return;\n        }\n\n        const+
