 barcode: \"\",\n            ebeln: \"\",\n            ebelp: \"\",\n            werks: \"\",\n            lgort: \"\",\n            matnr: \"\",\n            quantity: 1,\n            meins: \"\",\n            bwart: \"101\"\n        };\n    }\n\n    pr+
ivate updateQueue(aItems: GrItem[]): void {\n        this.getQueueModel().setData({\n            items: aItems,\n            count: aItems.length,\n            hasItems: aItems.length > 0\n        } as QueueData);\n    }\n\n    private createRequestId():+
